[ExtensionOf(formControlStr(VendEditInvoice, METTabButtonLineTaxTransSource))]
final class METVendEditInvoice_LineTaxButton_Extension
{
    private boolean isTaxServiceForPurchaseEnabled = Tax::isTaxIntegrationEnabledForBusinessProcess(TaxIntegrationBusinessProcess::Purchase);

}

Method.Source:
public void clicked()
{
    FormControl frmControl = this as FormControl;
    FormDataSource vendInvoiceInfoTableDataSource = frmControl.formRun().dataSource(tablestr(VendInvoiceInfoTable));
    FormDataSource vendInvoiceInfoLineDataSource = frmControl.formRun().dataSource(tableStr(VendInvoiceInfoLine));
    FormDataSource purchTableDataSource = frmControl.formRun().dataSource(tableStr(PurchTable));

    VendInvoiceInfoTable vendInvoiceInfoTable = vendInvoiceInfoTableDataSource.cursor();
    VendInvoiceInfoLine vendInvoiceInfoLine = vendInvoiceInfoLineDataSource.cursor();

    PurchTotals_ParmTransEdit::metShowTaxLine(menuitemDisplayStr(TaxTmpWorkVendInvoice), vendInvoiceInfoTable, vendInvoiceInfoLine, frmControl.formRun());

    if (isTaxServiceForPurchaseEnabled)
    {
        vendInvoiceInfoTableDataSource.reread();
        purchTableDataSource.reread();
        vendInvoiceInfoLineDataSource.research(true);
    }

    next clicked();
}
